:root {
  --bg-cream: #f2e8d5;
  --bg-card: #fdf6e8;
  --border-dark: #3b2a1a;
  --accent-red: #9b2d20;
  --accent-gold: #c8963e;
  --text-dark: #2a1a0e;
  --text-mid: #5c3d22;
  --text-light: #8a6540;
  --tag-bg: #9b2d20;
  --tag-text: #fdf6e8;
  --side-bg: #3b2a1a;
  --side-text: #f2e8d5;
  --highlight-bg: #f5ead0;
  --badge-bg: #c8963e;
  --badge-text: #2a1a0e;
}

.program {
  background-color: var(--bg-card);
  border: 2px solid var(--border-dark);
  border-radius: 4px;
  width: 460px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.program-header {
  background-color: var(--border-dark);
  color: var(--bg-cream);
  padding: 8px 14px 7px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  border-bottom: 3px solid var(--accent-gold);
}

.program-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 4px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.program-title {
  margin: 0;
  font-size: 17px;
  font-weight: 800;
  line-height: 1.2;
  color: var(--bg-cream);
}

.program-subtitle {
  margin: 0;
  font-size: 10px;
  color: var(--text-light);
  letter-spacing: 0.5px;
}

.program-body {
  display: flex;
  flex-direction: row;
  flex: 1;
}

.act-list {
  flex: 1;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  border-right: 1px solid var(--accent-gold);
}

.act {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 3px;
  border: 1px solid transparent;
}

.act--highlight {
  background-color: var(--highlight-bg);
  border-color: var(--accent-gold);
}

.act-num {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-red);
  width: 16px;
  text-align: center;
  flex-shrink: 0;
  font-style: italic;
}

.act-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.act-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dark);
}

.act-dur {
  font-size: 10px;
  color: var(--text-light);
}

.act-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  background-color: var(--tag-bg);
  color: var(--tag-text);
  padding: 2px 5px;
  border-radius: 2px;
}

.program-side {
  width: 110px;
  background-color: var(--side-bg);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.side-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.side-label {
  margin: 0;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.side-value {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  color: var(--side-text);
}

.admit-badge {
  margin-top: auto;
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  text-align: center;
  padding: 5px 6px;
  border-radius: 3px;
}

.program-footer {
  background-color: var(--bg-cream);
  border-top: 1px solid var(--accent-gold);
  padding: 5px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-note {
  font-size: 10px;
  color: var(--text-mid);
  font-style: italic;
}

.footer-serial {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-light);
  letter-spacing: 1px;
}
